create table public.classes (id uuid primary key default gen_random_uuid(), name text not null, code text not null, grade_level smallint not null check (grade_level between 10 and 12), academic_year text not null, semester smallint not null check (semester between 1 and 2), teacher_id uuid not null references public.profiles(id) on delete restrict, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());;
